use std::{fs,path::PathBuf};use serde_json::json;
struct Temp(PathBuf);impl Drop for Temp{fn drop(&mut self){let _=fs::remove_dir_all(&self.0);}}
fn temp()->Temp{let p=std::env::temp_dir().join(format!("sub08-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));fs::create_dir_all(&p).unwrap();Temp(p)}
fn project(t:&Temp)->(PathBuf,serde_json::Value){let audio=t.0.join("original.wav");fs::write(&audio,b"full quality original bytes").unwrap();let source=crate::audio_identity::info(&audio).unwrap();(audio,json!({"format":"whisperdesk-project-v1","id":"test","name":"Transcript","source":source,"cues":[]}))}
#[test]fn portable_audio_survives_original_deletion_and_unchanged_saves_do_nothing(){let t=temp();let(audio,mut p)=project(&t);let file=t.0.join("Test.subtitler");assert!(crate::audio_package::write(&file,&p).unwrap());let bytes=fs::read(&file).unwrap();assert!(!crate::audio_package::write(&file,&p).unwrap());assert_eq!(fs::read(&file).unwrap(),bytes);fs::remove_file(audio).unwrap();p["name"]=json!("Edited");crate::audio_package::write(&file,&p).unwrap();assert!(fs::read(&file).unwrap().starts_with(&bytes));let recovered=crate::audio_package::cached_audio(&file,&t.0.join("cache")).unwrap().unwrap();assert_eq!(fs::read(recovered).unwrap(),b"full quality original bytes");assert_eq!(crate::documents::read(&file).unwrap()["data"]["name"],"Edited");}
#[test]fn interrupted_last_save_recovers_previous_checkpoint(){let t=temp();let(_,mut p)=project(&t);let file=t.0.join("Test.subtitler");crate::audio_package::write(&file,&p).unwrap();p["name"]=json!("New");crate::audio_package::write(&file,&p).unwrap();fs::OpenOptions::new().write(true).open(&file).unwrap().set_len(fs::metadata(&file).unwrap().len()-4).unwrap();assert_eq!(crate::audio_package::read(&file).unwrap().project["name"],"Transcript");p["name"]=json!("Recovered");crate::audio_package::write(&file,&p).unwrap();assert_eq!(crate::audio_package::read(&file).unwrap().project["name"],"Recovered");}
#[test]fn recovery_never_overwrites_another_recording_and_detects_corruption(){use std::io::{Seek,SeekFrom,Write};let t=temp();let(_,p)=project(&t);let file=t.0.join("Test.subtitler");crate::audio_package::write(&file,&p).unwrap();let dest=t.0.join("Audio.wav");fs::write(&dest,b"preserve").unwrap();assert!(crate::audio_package::extract(&file,&dest,None).is_err());assert_eq!(fs::read(&dest).unwrap(),b"preserve");fs::remove_file(&dest).unwrap();let mut f=fs::OpenOptions::new().write(true).open(&file).unwrap();f.seek(SeekFrom::Start(18)).unwrap();f.write_all(b"X").unwrap();assert!(crate::audio_package::extract(&file,&dest,None).is_err());assert!(!dest.exists());}
#[test]fn legacy_missing_audio_preserves_text(){let t=temp();let file=t.0.join("Legacy.subtitler");let p=json!({"format":"whisperdesk-project-v1","id":"test","source":{"name":"Missing.wav","path":"/missing/audio.wav"},"cues":[],"referenceInput":{"text":"Keep me"}});fs::write(&file,p.to_string()).unwrap();assert_eq!(crate::documents::read(&file).unwrap()["data"]["referenceInput"]["text"],"Keep me");crate::documents::write(&file,&p.to_string()).unwrap();assert_eq!(crate::audio_package::read(&file).unwrap().project,p);assert!(crate::audio_package::cached_audio(&file,&t.0.join("cache")).unwrap().is_none());}
#[test]fn different_recording_cannot_replace_valid_embedded_audio(){let t=temp();let(audio,mut p)=project(&t);let file=t.0.join("Test.subtitler");crate::audio_package::write(&file,&p).unwrap();let before=fs::read(&file).unwrap();fs::write(audio,b"different").unwrap();p["source"]["fingerprint"]=json!("wrong");assert!(crate::audio_package::write(&file,&p).is_err());assert_eq!(fs::read(file).unwrap(),before);}
#[test]fn folder_move_preserves_audio_and_rebases_references_without_editing_user_text(){let t=temp();let(_,mut p)=project(&t);let old=t.0.join("Subtitler");fs::create_dir(&old).unwrap();let parent=t.0.join("New location");fs::create_dir(&parent).unwrap();let shared=t.0.join("Project/Studio Link");fs::create_dir_all(&shared).unwrap();let file=old.join("Test.subtitler");p["filePath"]=json!(file);p["referenceInput"]=json!({"text":file.to_string_lossy()});p["studioLink"]=json!({"directory":t.0.join("Project"),"projectFile":file});crate::audio_package::write(&file,&p).unwrap();fs::write(shared.join("subtitler-files.json"),json!({"recordings":{"x":{"path":file}}}).to_string()).unwrap();fs::write(old.join("readme.txt"),b"user file").unwrap();crate::library_folder::move_folder(&old,&parent).unwrap();let new=parent.join("Subtitler/Test.subtitler");assert!(!old.exists());let d=crate::audio_package::read(&new).unwrap();assert_eq!(d.project["filePath"],json!(new));assert_eq!(d.project["referenceInput"]["text"],p["referenceInput"]["text"]);let registry:serde_json::Value=serde_json::from_slice(&fs::read(shared.join("subtitler-files.json")).unwrap()).unwrap();assert_eq!(registry["recordings"]["x"]["path"],json!(new));assert_eq!(crate::library_folder::resolved(&file),new);assert_eq!(fs::read(parent.join("Subtitler/readme.txt")).unwrap(),b"user file");assert!(crate::audio_package::cached_audio(&new,&t.0.join("cache")).unwrap().is_some());}
#[test]fn folder_collision_preserves_both_locations(){let t=temp();let old=t.0.join("old/Subtitler");let parent=t.0.join("new");fs::create_dir_all(&old).unwrap();fs::create_dir_all(parent.join("Subtitler")).unwrap();fs::write(old.join("file"),b"original").unwrap();fs::write(parent.join("Subtitler/file"),b"other").unwrap();assert!(crate::library_folder::move_folder(&old,&parent).is_err());assert_eq!(fs::read(old.join("file")).unwrap(),b"original");assert_eq!(fs::read(parent.join("Subtitler/file")).unwrap(),b"other");}
#[test]fn linked_document_stays_in_normal_save_folder_with_one_shared_timing_handoff(){let t=temp();let(audio,mut p)=project(&t);let root=t.0.join("Storyboard project");let shared=root.join("Studio Link");fs::create_dir_all(&shared).unwrap();let folder=t.0.join("Subtitler");fs::create_dir(&folder).unwrap();let file=folder.join("Test.subtitler");p["filePath"]=json!(file);p["studioLink"]=json!({"directory":root,"projectId":"ss","projectFile":file});p["source"]["duration"]=json!(2);fs::write(shared.join("project.json"),json!({"format":"studio-link-project-v1","schemaVersion":1,"project":{"id":"ss"},"activeRecording":p["source"]}).to_string()).unwrap();fs::write(shared.join("spoken-script.json"),json!({"format":"subtitler-script-v1","studioProjectId":"ss"}).to_string()).unwrap();crate::audio_package::write(&file,&p).unwrap();let timing=json!({"format":"whisperdesk-timing-v1","projectId":"test","source":p["source"],"words":[{"id":"w","text":"Test","start":0,"end":1}]});let result=crate::project_files::save(root.to_str().unwrap(),Some("ss"),"test","Test.subtitler",&p.to_string(),&timing.to_string()).unwrap();assert_eq!(result["projectFile"],json!(file));assert!(!shared.join("Test.subtitler").exists());let handoff:serde_json::Value=serde_json::from_slice(&fs::read(shared.join("subtitler-audio.timing.json")).unwrap()).unwrap();assert_eq!(handoff["subtitlerProjectFile"],json!(file));assert_eq!(handoff["source"]["path"],json!(audio));let result=crate::project_files::inspect(root.to_str().unwrap(),Some("ss"),None).unwrap();assert_eq!(result["transcripts"].as_array().unwrap().len(),1);}
#[test]fn stale_cache_path_falls_back_to_original_and_upgrades_text_only_document(){let t=temp();let(audio,mut p)=project(&t);let file=t.0.join("Old.subtitler");fs::write(&file,p.to_string()).unwrap();p["source"]["embeddedPath"]=json!(t.0.join("missing-cache.wav"));assert!(crate::audio_package::write(&file,&p).unwrap());fs::remove_file(audio).unwrap();let cached=crate::audio_package::cached_audio(&file,&t.0.join("cache")).unwrap().unwrap();assert_eq!(fs::read(cached).unwrap(),b"full quality original bytes");assert_eq!(crate::audio_package::read(&file).unwrap().project["id"],"test");}
